const storageKey = 'automation-scheduling-regression-run-count';
const runCount = Number(sessionStorage.getItem(storageKey) ?? '0') + 1;
sessionStorage.setItem(storageKey, String(runCount));
let status = document.querySelector('[data-scheduling-regression-status]');
if (!(status instanceof HTMLElement)) {
  status = document.createElement('div');
  status.dataset.schedulingRegressionStatus = '';
  status.style.cssText = 'margin-top:16px;padding:14px;border-radius:10px;background:#fff4cc;color:#5f4700;font:700 14px/1.4 system-ui,sans-serif';
  document.querySelector('main')?.append(status);
}
status.dataset.runCount = String(runCount);
status.textContent = `Scheduling run ${runCount}: running`;
automation.log({ event: 'scheduling-run-started', runCount, title: document.title });
return { runCount, state: 'running' };

const status = document.querySelector('[data-scheduling-regression-status]');
if (!(status instanceof HTMLElement)) { throw new Error('Scheduling status marker was not found'); }
const runCount = Number(status.dataset.runCount);
status.style.background = '#dff7e8';
status.style.color = '#14532d';
status.textContent = `Scheduling run ${runCount}: completed`;
automation.log({ event: 'scheduling-run-completed', runCount, title: document.title });
return { runCount, state: 'completed' };
